/**
 * src/main.js
 * 應用程式主入口
 */

(function(root) {
  'use strict';

  var Constants = window.AppConstants || {};
  var State = window.AppState || {};
  var Storage = window.StorageAPI || {};
  var Router = window.AppRouter || {};
  var Audit = window.AuditLog || {};

  /**
   * 初始化應用程式
   */
  function initialize() {
    console.log('Initializing IRR Tracker v' + Constants.VERSION);

    // 1. 初始化儲存系統
    var db = Storage.initialize ? Storage.initialize() : null;
    if (!db) {
      console.error('Failed to initialize storage');
      db = {
        schemaVersion: Constants.SCHEMA_VERSION,
        version: 1,
        projects: [],
        notices: [],
        auditLogs: [],
        today: new Date().toISOString().slice(0, 10),
        seq: 1
      };
    }

    // 2. 同步到全局狀態
    if (State.setDb) {
      State.setDb(db);
    }

    // 3. 記錄應用啟動
    if (Audit.log) {
      Audit.log('app_start', {
        resourceType: 'system',
        resourceId: 'main',
        details: {
          version: Constants.VERSION,
          schemaVersion: Constants.SCHEMA_VERSION
        }
      });
    }

    // 4. 綁定導航事件
    bindNavigation();

    // 5. 綁定日期選擇器
    bindDatePicker();

    // 6. 嘗試載入 SEED 資料
    loadSeedData();

    // 7. 導航到首頁
    Router.navigate('/');

    console.log('✅ Application initialized');
  }

  /**
   * 綁定導航事件
   */
  function bindNavigation() {
    var nav = document.getElementById('nav');
    if (!nav) return;

    var pages = Constants.PAGES || {};
    var links = [];

    for (var page in pages) {
      if (pages.hasOwnProperty(page)) {
        links.push({
          name: pages[page],
          label: getPageLabel(pages[page])
        });
      }
    }

    nav.innerHTML = links.map(function(link) {
      return '<a href="#' + link.name + '" data-page="' + link.name + '">' + link.label + '</a>';
    }).join('');

    nav.addEventListener('click', function(e) {
      if (e.target.tagName === 'A') {
        e.preventDefault();
        var page = e.target.getAttribute('data-page');
        Router.navigate('/' + page);
      }
    });
  }

  /**
   * 取得頁面標籤
   */
  function getPageLabel(page) {
    var labels = {
      'overview': '概覽',
      'project': '專案',
      'upload': '上傳',
      'notices': '通知',
      'audit': '審計',
      'backup': '備份'
    };
    return labels[page] || page;
  }

  /**
   * 綁定日期選擇器
   */
  function bindDatePicker() {
    var todayInput = document.getElementById('today');
    if (!todayInput) return;

    var today = new Date().toISOString().slice(0, 10);
    todayInput.value = today;

    todayInput.addEventListener('change', function() {
      if (State.state && State.state.db) {
        State.state.db.today = this.value;
        State.set({ db: State.state.db });
      }
    });
  }

  /**
   * 嘗試載入示例資料
   */
  function loadSeedData() {
    fetch('/demo/seed.json')
      .then(function(r) { return r.json(); })
      .then(function(seed) {
        console.log('✓ Loaded seed data');
        // 可以在此處用示例資料初始化應用
      })
      .catch(function(e) {
        // 本機 file:// 或線上環境中無 /demo/seed.json 時正常失敗
        console.log('No seed data available (expected in production)');
      });
  }

  // ========== 應用啟動 ==========
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initialize);
  } else {
    initialize();
  }

})(typeof window !== 'undefined' ? window : globalThis);
